#if UNITY_EDITOR
using LastRail.Battle;
using NUnit.Framework;
using System;
using System.IO;
using Newtonsoft.Json.Linq;
namespace LastRail.Tests.EditMode {
 public sealed class EquipmentDepartureBasePinTests {
  const string SamplePath="D:/Project/LASTRAIL/QA/CommanderS1-20260922/equipment-departure-source-sql-sample-20261005.json";
  const string Pin="a5e53f1d0f8894505a61ba79fd8481aa94b36ab70210535ef217e70009a34be4";
  const string Run="run_0db228e2-2642-47a5-8d23-d896871b30cd";
  static JObject Sample()=>JObject.Parse(File.ReadAllText(SamplePath));
  static string Original()=>(string)Sample()["originalSnapshotJson"];
  static EquipmentDepartureBasePin Read(string raw=null,string trusted=null,string pin=Pin,string account="a",string run=Run)=>EquipmentDepartureBasePin.Read(raw??Original(),trusted??Original(),pin,account,run);
  static string Digest(JToken x)=>BDirectAttackInput.Digest(x).Substring(7);
  static void Rehash(JObject root) {var p=(JObject)root["equipmentDeparturePin"];foreach(var k in new[]{"origin","source","definitions"})p[k=="definitions"?"definitionHash":k+"Hash"]=Digest(p[k]);p["admissionHash"]=Digest(root["admission"]);p.Remove("pinHash");p["pinHash"]=Digest(p);root["departureResponse"]["equipmentDeparturePin"]=p.DeepClone();}
  [Test] public void PermanentDeparturePinNeedsIndependentImmutableBoundary(){Assert.NotNull(typeof(BDirectAttackInput).Assembly.GetType("LastRail.Battle.EquipmentDepartureBasePin"));}
  [Test] public void OriginalSqlPinPreservesFiveExactPermanentBases(){var s=Read();Assert.AreEqual(Pin,s.Hash);Assert.AreEqual(Run,s.RunId);Assert.AreEqual("a",s.AccountId);Assert.AreEqual(5,((JArray)s.Capture()["origin"]["actors"]).Count);Assert.IsTrue(JToken.DeepEquals(Sample()["originalPin"],s.Capture()));Assert.AreEqual(1400,(int)s.ActorBase("op_kyle")["maxHp"]);Assert.AreEqual("3600000000",(string)s.ActorBase("op_kyle")["attack"]["numerator"]);Assert.AreEqual("100000000",(string)s.ActorBase("op_kyle")["attack"]["denominator"]);Assert.AreEqual(1600,(int)s.ActorBase("op_sable")["maxHp"]);Assert.AreEqual(900,(int)s.ActorBase("op_reina")["maxHp"]);Assert.AreEqual(950,(int)s.ActorBase("op_eve")["maxHp"]);Assert.AreEqual(920,(int)s.ActorBase("op_sera")["maxHp"]);}
  [Test] public void CloneMutationCannotChangeOriginalAndRestorationNeedsNoCurrentOwnership(){var s=Read();s.Capture()["origin"]["actors"][0]["base"]["maxHp"]=1;s.ActorBase("op_kyle")["maxHp"]=2;Assert.AreEqual(1400,(int)s.ActorBase("op_kyle")["maxHp"]);Assert.IsTrue(JToken.DeepEquals(s.Capture(),Read().Capture()));Assert.IsTrue((bool)Sample()["restoreAfterCurrentGrowthChangeVerified"]);Assert.IsTrue((bool)Sample()["sameKeyReplayVerified"]);}
  [TestCase("account")][TestCase("run")][TestCase("pin")]
  public void IndependentOwnerAndHashCannotBeReplaced(string f){Assert.Throws<ArgumentException>(()=>Read(null,null,f=="pin"?new string('0',64):Pin,f=="account"?"foreign":"a",f=="run"?"foreign":Run));}
  [TestCase("origin")][TestCase("source")][TestCase("definitions")][TestCase("admission")][TestCase("response")][TestCase("rootRun")][TestCase("responseRun")][TestCase("version")]
  public void RehashedChangedSnapshotCannotReplaceOriginal(string f){var root=JObject.Parse(Original());if(f=="origin")root["equipmentDeparturePin"]["origin"]["actors"][0]["base"]["maxHp"]=999;if(f=="source")root["equipmentDeparturePin"]["source"]["ownedProfile"]["formationRevision"]=2;if(f=="definitions")root["equipmentDeparturePin"]["definitions"]["extra"]=1;if(f=="admission")root["admission"]["formationRevision"]=2;if(f=="rootRun")root["runId"]="foreign";if(f=="responseRun")root["departureResponse"]["runId"]="foreign";if(f=="version")root["equipmentDeparturePin"]["version"]="old";Rehash(root);if(f=="response")root["departureResponse"]["equipmentDeparturePin"]["risk"]="II";Assert.Throws<ArgumentException>(()=>Read(root.ToString()));}
  [TestCase("actorKind")][TestCase("duplicate")][TestCase("target")][TestCase("stage")][TestCase("empty")][TestCase("hp")][TestCase("fraction")][TestCase("runtime")][TestCase("selected")][TestCase("unknown")][TestCase("capacity")]
  public void DiagnosticSelfPinnedMalformedSourceStillCannotWidenContract(string f){var root=JObject.Parse(Original());var p=(JObject)root["equipmentDeparturePin"];var actors=(JArray)p["origin"]["actors"];if(f=="actorKind")actors[0]["wearerKind"]="turret";if(f=="duplicate")actors[1]=actors[0].DeepClone();if(f=="target")actors[0]["targetId"]="alias";if(f=="stage")p["origin"]["stage"]="CURRENT_OWNED";if(f=="empty")actors.Clear();if(f=="hp")actors[0]["base"]["maxHp"]=0;if(f=="fraction")actors[0]["base"]["attack"]["denominator"]="0";if(f=="runtime")p["source"]["runtimeSupported"]=true;if(f=="selected")p["source"]["ownedProfile"]["operators"][0]["operatorId"]="foreign";if(f=="unknown")p["extra"]=1;if(f=="capacity")p["source"]["oversized"]=new string('x',524288);Rehash(root);string raw=root.ToString();Assert.Throws<ArgumentException>(()=>Read(raw,raw,(string)p["pinHash"]));}
  [TestCase(false)][TestCase(true)] public void LegacyMissingOrNullPinRemainsUnsupported(bool explicitNull){var root=JObject.Parse(Original());foreach(var o in new[]{root,(JObject)root["departureResponse"]}){o.Remove("equipmentDeparturePin");if(explicitNull)o["equipmentDeparturePin"]=JValue.CreateNull();}Assert.IsNull(Read(root.ToString(),root.ToString()));Assert.Throws<ArgumentException>(()=>Read(root.ToString()));root["departureResponse"]["equipmentDeparturePin"]=Sample()["originalPin"].DeepClone();Assert.Throws<ArgumentException>(()=>Read(root.ToString(),root.ToString()));}
  [Test] public void StrictJsonRejectsDuplicatesTrailingAndComments(){string raw=Original();Assert.Throws<Newtonsoft.Json.JsonReaderException>(()=>Read("{\"x\":1,\"x\":2}"));Assert.Throws<Newtonsoft.Json.JsonReaderException>(()=>Read(raw+"{}"));Assert.Throws<ArgumentException>(()=>Read(raw.Insert(1,"/*test*/")));}
  [Test] public void PermanentPinGrantsNoSafeMaintenanceOrFinalRuntimeStats(){var s=Read();Assert.IsFalse(s.CanProveSafeMaintenance);Assert.IsFalse(s.CanApplyRuntimeFinalEffects);Assert.Throws<InvalidOperationException>(()=>s.RequireSafeMaintenance());Assert.Throws<ArgumentException>(()=>s.ActorBase("turret"));var f=BNamedOperatorSourceTests.Native();var n=f.adapter.CreateRuntime(f.binding,BOrdinaryGeometryTests.Geometry(f.binding),10000);var before=n.Capture();s.ActorBase("op_kyle");Assert.IsTrue(JToken.DeepEquals(before,n.Capture()));Assert.AreEqual(1400,n.Hp("op_kyle"));}
 }
}
#endif
